namespace Clc.Polaris.Api.UnitTests.Models { [TestClass][UnitTest] public sealed class JobsPurchaseOrdersPreorderValidationResultJsonDeserializationTests { [TestMethod] public void RoundTripsDocumentedShape() { var json = """{"PAPIErrorCode":1,"ExternalID":"e","LineItemValidationErrors":[{"ExternalID":"l","ValidationErrors":[{"Field":"Vendor","Message":"bad"}]}]}"""; var r = System.Text.Json.JsonSerializer.Deserialize<JobsPurchaseOrdersPreorderValidationResult>(json)!; Assert.AreEqual(1, r.PAPIErrorCode); Assert.AreEqual("e", r.ExternalID); Assert.AreEqual("l", r.LineItemValidationErrors![0].ExternalID); Assert.AreEqual("Vendor", r.LineItemValidationErrors[0].ValidationErrors![0].Field); } } }
